style.css:
@-moz-document domain("chat.openai.com") {
body,
    body * {
        color: #1a1a1a !important; /* deep gray, almost black */
    }

    /* Ensure code blocks and inline code also change */
    pre,
    code {
        color: #1a1a1a !important;
    }

    /* Override links */
    a,
    a * {
        color: #1a1a1a !important;
    }

    /* Override markdown elements */
    .markdown,
    .markdown *,
    .prose,
    .prose * {
        color: #1a1a1a !important;
    }

    /* Override chat bubbles */
    .group,
    .group * {
        color: #1a1a1a !important;
    }

    /* Override message containers */
    .message,
    .message * {
        color: #1a1a1a !important;
    }

    /* Override buttons and labels */
    button,
    button *,
    label,
    label * {
        color: #1a1a1a !important;
    }
}
